#define COL_BASE vec3(0.429, 0.632, 0.780)
#define COL_CONT vec3(0.510, 0.567, 0.838)
#define COL_FREQ vec3(0.963, 0.539, 1.495)
#define COL_PHAS vec3(0.620, 4.984, 1.241)

#define ROT_SPEED 0.1
#define WARP_INIT 1.0
#define WARP_ITER 2.0
#define WARP_AMPL 2.0

vec3 palette(float t) {
   return COL_BASE + COL_CONT * cos(radians(360.0) * (t * COL_FREQ + COL_PHAS));
}

vec2 rotate(vec2 uv) {
   float angle = iTime * ROT_SPEED;
   float s = sin(angle);
   float c = cos(angle);

   return mat2(c, - s, s, c) * uv;
}

vec2 warp(vec2 uv) {
   for(float i = WARP_INIT; i < WARP_ITER; i ++ ) {
      float oscillationX = sin(i * 0.5 + iTime * 0.25) * cos(iTime + uv.y * 1.5);
      float oscillationY = cos(i * 0.7 + iTime * 0.35) * sin(iTime + uv.x * 1.2);

      uv.x += WARP_AMPL / i * (oscillationX + 0.2 * sin(iTime * 0.6 + uv.y * 3.0));
      uv.y += WARP_AMPL / i * (oscillationY + 0.3 * cos(iTime * 0.8 + uv.x * 2.5));
   }

   return uv;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
   vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

   uv = rotate(uv);
   uv = warp(uv);

   fragColor = vec4(palette(abs(sin(iTime - uv.y - uv.x))), 1.0);
}
